import { mkdir, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { config } from '../../../config';
import type { ImageStore } from './types';

/** Only keys the server generates: a UUID plus a known image extension. */
const KEY_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(?:jpg|png|webp)$/;

/**
 * Resolves a key to a file inside `UPLOAD_DIR`. Keys are generated by the
 * server, but checking them here as well means no path (`../`, `/etc/…`)
 * can ever be written or deleted through this store.
 */
const filePath = (key: string) => {
  if (!KEY_PATTERN.test(key)) {
    throw new Error(`Refusing unexpected upload key: ${JSON.stringify(key)}`);
  }
  return path.join(config.uploadDir, key);
};

/**
 * Images on the API server's disk (`UPLOAD_DIR`; a named volume in Docker),
 * served by the API under `/uploads` (see `app.ts`).
 *
 * Chosen so the project runs with one command, offline, with no cloud
 * account or credentials. It only works with a single API instance, which is
 * why it sits behind `ImageStore`: production would use an S3 store instead.
 */
export const localDiskStore: ImageStore = {
  put: async (key, bytes) => {
    const target = filePath(key);
    await mkdir(config.uploadDir, { recursive: true });
    // `wx`: never overwrite an existing file.
    await writeFile(target, bytes, { flag: 'wx' });
  },
  remove: async (key) => {
    await unlink(filePath(key)).catch((error: NodeJS.ErrnoException) => {
      if (error.code !== 'ENOENT') {
        throw error;
      }
    });
  },
  publicUrl: (key) => `${config.uploadsPublicPath}/${key}`
};
